pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Base64.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/metadatacomponents/ERC2981.sol";

contract WhitelistRevealNFT is ERC721, ERC721URIStorage, Ownable, ERC2981 {
    using Strings for uint256;
    using Base64 for bytes;

    // --- State Variables ---

    // Whitelist
    mapping(address => bool) public isWhitelisted;
    uint256 public whitelistMintLimit; // Max NFTs per whitelisted address

    // Minting
    uint256 public maxSupply;
    uint256 public pricePerNFT;
    uint256 public mintStartTime;
    uint256 public mintEndTime;
    uint256 public mintCount; // Total NFTs minted

    // Reveal Mechanism
    string public baseURI; // Base URI for revealed NFTs
    string public hiddenMetadataURI; // URI for hidden metadata before reveal
    bool public revealed = false;
    uint256 public revealStartTime;

    // Royalties (EIP-2981)
    address public royaltyRecipient;
    uint96 public royaltyPercentageBasisPoints; // 10000 = 100%

    // --- Events ---
    event WhitelistAddressAdded(address indexed addr);
    event WhitelistAddressRemoved(address indexed addr);
    event WhitelistMintLimitChanged(uint256 newLimit);
    event MintConfigChanged(uint256 maxSupply, uint256 pricePerNFT, uint256 mintStartTime, uint256 mintEndTime);
    event RevealConfigChanged(string baseURI, string hiddenMetadataURI, uint256 revealStartTime);
    event RoyaltiesChanged(address indexed recipient, uint96 percentage);
    event Minted(address indexed owner, uint256 indexed tokenId);
    event Revealed();

    // --- Constructor ---
    constructor(
        string memory _name,
        string memory _symbol,
        uint256 _maxSupply,
        uint256 _pricePerNFT,
        uint256 _mintStartTime,
        uint256 _mintEndTime,
        uint256 _revealStartTime,
        string memory _hiddenMetadataURI,
        address _royaltyRecipient,
        uint96 _royaltyPercentageBasisPoints
    ) ERC721(_name, _symbol) Ownable(msg.sender) {
        require(_maxSupply > 0, "Max supply must be greater than 0");
        require(_pricePerNFT > 0, "Price per NFT must be greater than 0");
        require(_mintStartTime < _mintEndTime, "Mint start time must be before end time");
        require(_revealStartTime > _mintEndTime, "Reveal start time must be after mint end time");
        require(_hiddenMetadataURI != "", "Hidden metadata URI cannot be empty");
        require(_royaltyRecipient != address(0), "Royalty recipient cannot be the zero address");
        require(_royaltyPercentageBasisPoints <= 10000, "Royalty percentage cannot exceed 100%");

        maxSupply = _maxSupply;
        pricePerNFT = _pricePerNFT;
        mintStartTime = _mintStartTime;
        mintEndTime = _mintEndTime;
        revealStartTime = _revealStartTime;
        hiddenMetadataURI = _hiddenMetadataURI;
        royaltyRecipient = _royaltyRecipient;
        royaltyPercentageBasisPoints = _royaltyPercentageBasisPoints;

        // Default whitelist mint limit
        whitelistMintLimit = 1;
    }

    // --- Whitelist Management ---

    function addWhitelistedAddress(address _addr) public onlyOwner {
        require(_addr != address(0), "Invalid address");
        isWhitelisted[_addr] = true;
        emit WhitelistAddressAdded(_addr);
    }

    function removeWhitelistedAddress(address _addr) public onlyOwner {
        require(_addr != address(0), "Invalid address");
        isWhitelisted[_addr] = false;
        emit WhitelistAddressRemoved(_addr);
    }

    function setWhitelistMintLimit(uint256 _limit) public onlyOwner {
        whitelistMintLimit = _limit;
        emit WhitelistMintLimitChanged(_limit);
    }

    // --- Minting ---

    function mint(uint256 _quantity) public payable {
        require(block.timestamp >= mintStartTime, "Minting has not started yet");
        require(block.timestamp < mintEndTime, "Minting has ended");
        require(_quantity > 0, "Quantity must be greater than 0");
        require(mintCount + _quantity <= maxSupply, "Exceeds max supply");

        // Whitelist check
        require(isWhitelisted[msg.sender], "Not whitelisted");
        // You might want to track how many NFTs a whitelisted address has already minted
        // For simplicity, this example doesn't track individual whitelist mint counts per address
        // but relies on the global whitelistMintLimit for a single mint action.
        // A more robust implementation would involve a mapping: mapping(address => uint256) public whitelistMintedCount;

        require(msg.value >= pricePerNFT * _quantity, "Insufficient payment");

        for (uint256 i = 0; i < _quantity; i++) {
            uint256 tokenId = mintCount + 1;
            _safeMint(msg.sender, tokenId);
            mintCount++;
            emit Minted(msg.sender, tokenId);
        }

        // If the contract receives more Ether than required, it's kept by the contract owner.
        // You might want to implement a withdrawal function for the owner.
    }

    // --- Reveal Mechanism ---

    function setRevealConfig(string memory _baseURI, uint256 _revealStartTime) public onlyOwner {
        require(_baseURI != "", "Base URI cannot be empty");
        require(_revealStartTime > mintEndTime, "Reveal start time must be after mint end time");
        baseURI = _baseURI;
        revealStartTime = _revealStartTime;
        emit RevealConfigChanged(baseURI, hiddenMetadataURI, revealStartTime);
    }

    function reveal() public {
        require(block.timestamp >= revealStartTime, "Reveal has not started yet");
        require(!revealed, "Already revealed");
        revealed = true;
        emit Revealed();
    }

    // --- Royalties (EIP-2981) ---

    function supportsInterface(bytes4 interfaceId) public view virtual override(ERC721, ERC2981) returns (bool) {
        return super.supportsInterface(interfaceId);
    }

    function royaltyInfo(uint256 tokenId, uint256 salePrice)
        public
        view
        virtual
        override(ERC2981)
        returns (address receiver, uint256 royaltyAmount)
    {
        // Only apply royalties if the token has been revealed
        if (revealed) {
            return (royaltyRecipient, (salePrice * royaltyPercentageBasisPoints) / 10000);
        } else {
            return (address(0), 0); // No royalties before reveal
        }
    }

    function setRoyalties(address _recipient, uint96 _percentage) public onlyOwner {
        require(_recipient != address(0), "Royalty recipient cannot be the zero address");
        require(_percentage <= 10000, "Royalty percentage cannot exceed 100%");
        royaltyRecipient = _recipient;
        royaltyPercentageBasisPoints = _percentage;
        emit RoyaltiesChanged(_recipient, _percentage);
    }

    // --- Metadata ---

    function _baseURI() internal view override returns (string memory) {
        return baseURI;
    }

    function tokenURI(uint256 tokenId) public view override(ERC721, ERC721URIStorage) returns (string memory) {
        _requireMinted(tokenId);

        if (revealed) {
            // If revealed, construct the URI using the baseURI and token ID
            return string(abi.encodePacked(baseURI, tokenId.toString()));
        } else {
            // If not revealed, return the hidden metadata URI
            return hiddenMetadataURI;
        }
    }

    // --- Owner Functions ---

    function withdraw() public onlyOwner {
        (bool success, ) = payable(owner()).call{value: address(this).balance}("");
        require(success, "Withdrawal failed");
    }

    function setMintConfig(
        uint256 _maxSupply,
        uint256 _pricePerNFT,
        uint256 _mintStartTime,
        uint256 _mintEndTime
    ) public onlyOwner {
        require(_maxSupply > 0, "Max supply must be greater than 0");
        require(_pricePerNFT > 0, "Price per NFT must be greater than 0");
        require(_mintStartTime < _mintEndTime, "Mint start time must be before end time");
        maxSupply = _maxSupply;
        pricePerNFT = _pricePerNFT;
        mintStartTime = _mintStartTime;
        mintEndTime = _mintEndTime;
        emit MintConfigChanged(_maxSupply, _pricePerNFT, _mintStartTime, _mintEndTime);
    }

    // --- Fallback and Receive ---
    receive() external payable {}
    fallback() external payable {}
}

