pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/utils/Base64.sol";

contract ProductionERC1155 is ERC1155, Ownable {
    using Strings for uint256;

    // --- State Variables ---

    // Mapping from token ID to its crafting recipe
    struct CraftingRecipe {
        uint256 outputTokenId;
        uint256 outputAmount;
        mapping(uint256 => uint256) inputTokens; // tokenId => amount
    }

    // Stores all defined crafting recipes
    CraftingRecipe[] public recipes;
    // Maps a recipe index to its details
    mapping(uint256 => CraftingRecipe) public recipeDetails;
    // Tracks the next available recipe ID
    uint256 public nextRecipeId;

    // Base URI for metadata. Can be dynamic based on token ID.
    string public baseURI;

    // --- Events ---

    event TokenCrafted(
        address indexed crafter,
        uint256 outputTokenId,
        uint256 outputAmount,
        uint256 recipeId
    );

    event RecipeAdded(uint256 indexed recipeId, uint256 outputTokenId, uint256 outputAmount);
    event RecipeInputAdded(uint256 indexed recipeId, uint256 inputTokenId, uint256 inputAmount);
    event RecipeRemoved(uint256 indexed recipeId);

    // --- Constructor ---

    constructor(string memory _baseURI) ERC1155(_baseURI) Ownable(msg.sender) {
        baseURI = _baseURI;
        nextRecipeId = 0;
    }

    // --- Modifier ---

    modifier onlyRecipeOwner(uint256 _recipeId) {
        // In a more complex scenario, you might want to assign recipe ownership.
        // For simplicity here, we assume only the contract owner can manage recipes.
        require(msg.sender == owner(), "Not the owner");
        _;
    }

    // --- Core ERC1155 Functions (Overridden for custom logic) ---

    function uri(uint256 _tokenId) public view override returns (string memory) {
        // Basic URI generation. Can be extended for dynamic metadata.
        // Example: if baseURI is "ipfs://Qm...", and _tokenId is 1, it returns "ipfs://Qm.../1.json"
        return string(abi.encodePacked(super.uri(_tokenId), _tokenId.toString(), ".json"));
    }

    // --- Token Crafting Functions ---

    /**
     * @notice Adds a new crafting recipe.
     * @param _outputTokenId The ID of the token to be minted.
     * @param _outputAmount The amount of the output token to be minted.
     */
    function addRecipe(uint256 _outputTokenId, uint256 _outputAmount)
        public
        onlyOwner
        returns (uint256)
    {
        uint256 recipeId = nextRecipeId;
        recipes.push(); // Add a new slot for the recipe
        recipeDetails[recipeId].outputTokenId = _outputTokenId;
        recipeDetails[recipeId].outputAmount = _outputAmount;
        nextRecipeId++;
        emit RecipeAdded(recipeId, _outputTokenId, _outputAmount);
        return recipeId;
    }

    /**
     * @notice Adds an input token requirement to an existing recipe.
     * @param _recipeId The ID of the recipe to modify.
     * @param _inputTokenId The ID of the required input token.
     * @param _inputAmount The amount of the input token required.
     */
    function addRecipeInput(
        uint256 _recipeId,
        uint256 _inputTokenId,
        uint256 _inputAmount
    ) public onlyRecipeOwner(_recipeId) {
        require(_recipeId < nextRecipeId, "Recipe does not exist");
        require(_inputAmount > 0, "Input amount must be greater than 0");
        recipeDetails[_recipeId].inputTokens[_inputTokenId] = _inputAmount;
        emit RecipeInputAdded(_recipeId, _inputTokenId, _inputAmount);
    }

    /**
     * @notice Crafts a new token by burning required input tokens.
     * @param _recipeId The ID of the recipe to use.
     */
    function craftToken(uint256 _recipeId) public {
        require(_recipeId < nextRecipeId, "Recipe does not exist");

        CraftingRecipe storage recipe = recipeDetails[_recipeId];
        uint256 outputTokenId = recipe.outputTokenId;
        uint256 outputAmount = recipe.outputAmount;

        // Check if the caller has enough input tokens
        for (uint256 i = 0; i < recipes.length; i++) { // Iterate through the dynamic array of inputs for this recipe
            if (recipe.inputTokens[i] > 0) { // Check if there's an input for this token ID
                require(
                    balanceOf(msg.sender, i) >= recipe.inputTokens[i],
                    "Insufficient input tokens"
                );
            }
        }

        // Burn input tokens
        for (uint256 i = 0; i < recipes.length; i++) {
            if (recipe.inputTokens[i] > 0) {
                _burn(msg.sender, i, recipe.inputTokens[i]);
            }
        }

        // Mint output token
        _mint(msg.sender, outputTokenId, outputAmount, "");

        emit TokenCrafted(msg.sender, outputTokenId, outputAmount, _recipeId);
    }

    /**
     * @notice Allows the owner to remove a crafting recipe.
     * @param _recipeId The ID of the recipe to remove.
     */
    function removeRecipe(uint256 _recipeId) public onlyRecipeOwner(_recipeId) {
        require(_recipeId < nextRecipeId, "Recipe does not exist");
        // Mark recipe as inactive or set output to 0 to effectively remove it.
        // A more robust solution might involve shifting recipes or using a boolean flag.
        // For simplicity, we'll zero out the output and input amounts.
        recipeDetails[_recipeId].outputTokenId = 0;
        recipeDetails[_recipeId].outputAmount = 0;
        // Clearing mappings in Solidity is not straightforward.
        // We'll rely on checking outputAmount > 0 to consider a recipe valid.
        emit RecipeRemoved(_recipeId);
    }


    // --- Dynamic Metadata Functions ---

    /**
     * @notice Sets the base URI for all tokens.
     * @param _newBaseURI The new base URI.
     */
    function setBaseURI(string memory _newBaseURI) public onlyOwner {
        baseURI = _newBaseURI;
        // Note: Changing baseURI might require re-minting tokens or using a more complex metadata system
        // if existing tokens need to reflect the new base URI immediately.
        // For ERC1155, token URIs are typically resolved by appending the token ID to the base URI.
        // If the _newBaseURI is a contract address, you might need to implement a function to fetch metadata from that contract.
    }

    /**
     * @notice Generates SVG metadata for a given token ID.
     * @dev This is a simplified example. Real-world dynamic metadata can be much more complex.
     * @param _tokenId The ID of the token.
     * @return JSON string representing the metadata.
     */
    function generateSVGBasedMetadata(uint256 _tokenId) public view returns (string memory) {
        // Example: Token 1 might be 'Wood', Token 2 'Stone', Token 3 'Iron Ore'
        // Token 4 might be 'Wooden Sword' (crafted from wood)

        string memory name;
        string memory description;
        string memory imageURI; // This will be an SVG

        if (_tokenId == 1) {
            name = "Wood";
            description = "A simple piece of wood.";
            imageURI = '<svg width="100" height="100" xmlns="http://www.w3.org/2000/svg"><rect width="100" height="100" fill="saddlebrown"/></svg>';
        } else if (_tokenId == 2) {
            name = "Stone";
            description = "A rough stone.";
            imageURI = '<svg width="100" height="100" xmlns="http://www.w3.org/2000/svg"><rect width="100" height="100" fill="dimgray"/></svg>';
        } else if (_tokenId == 3) {
            name = "Iron Ore";
            description = "A chunk of iron ore.";
            imageURI = '<svg width="100" height="100" xmlns="http://www.w3.org/2000/svg"><rect width="100" height="100" fill="gray"/></svg>';
        } else if (_tokenId == 4) {
            name = "Wooden Sword";
            description = "A basic sword made of wood.";
            imageURI = '<svg width="100" height="100" xmlns="http://www.w3.org/2000/svg"><path d="M20 10 L80 10 L70 90 L30 90 Z" fill="saddlebrown" stroke="black" stroke-width="2"/></svg>';
        } else {
            name = string(abi.encodePacked("Unknown Item ", _tokenId.toString()));
            description = "An item with unknown properties.";
            imageURI = '<svg width="100" height="100" xmlns="http://www.w3.org/2000/svg"><rect width="100" height="100" fill="black"/></svg>';
        }

        // Construct the JSON metadata
        // The 'image' field will contain the SVG data encoded in base64
        string memory jsonMetadata = string(abi.encodePacked(
            '{"name": "', name,
            '", "description": "', description,
            '", "image": "data:image/svg+xml;base64,', Base64.encode(bytes(imageURI)), '"}'
        ));

        return jsonMetadata;
    }

    /**
     * @notice Returns the metadata URI for a given token ID, potentially pointing to dynamic metadata.
     * @param _tokenId The ID of the token.
     * @return The metadata URI.
     */
    function getTokenMetadataURI(uint256 _tokenId) public view returns (string memory) {
        // This function can be used to dynamically generate metadata.
        // The `uri` function is called by marketplaces to fetch metadata.
        // If you want to serve dynamic metadata directly from the contract,
        // you would return a data URI here.
        // For example: "data:application/json;base64,..."

        // In this example, we'll return a data URI that points to dynamically generated SVG metadata.
        // This requires a marketplace or client that can interpret data URIs.
        // Alternatively, you could have a separate off-chain service that generates metadata based on the token ID and contract address.

        string memory jsonMetadata = generateSVGBasedMetadata(_tokenId);
        return string(abi.encodePacked("data:application/json;base64,", Base64.encode(bytes(jsonMetadata))));

        // If you are using a decentralized storage like IPFS, you would return the IPFS URI.
        // return string(abi.encodePacked(baseURI, _tokenId.toString(), ".json"));
    }

    // --- Marketplace Integration ---
    // ERC1155 already provides the necessary interfaces for marketplaces (like OpenSea).
    // Marketplaces typically interact with the contract by:
    // 1. Calling `balanceOf(owner, tokenId)` to check ownership.
    // 2. Calling `uri(tokenId)` or `getTokenMetadataURI(tokenId)` to fetch metadata.
    // 3. Transferring tokens using `safeTransferFrom` or `transferBatch`.

    // --- Utility Functions ---

    /**
     * @notice A helper function to check if a recipe exists and is valid.
     * @param _recipeId The ID of the recipe.
     * @return True if the recipe is valid, false otherwise.
     */
    function isRecipeValid(uint256 _recipeId) public view returns (bool) {
        return _recipeId < nextRecipeId && recipeDetails[_recipeId].outputAmount > 0;
    }

    // --- Internal Functions (for potential future extensions) ---
    // _beforeTokenTransfer, _afterTokenTransfer, etc.
}

