pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/math/SafeMath.sol";

contract LiquidStaking is ERC20, Ownable {
    using SafeMath for uint256;

    // The underlying asset to be staked (e.g., ETH, DAI, etc.)
    IERC20 public immutable stakingToken;

    // The receipt token representing the staked position
    string public constant NAME = "Staked Token";
    string public constant SYMBOL = "stToken";

    // Mapping from stToken holder to their staked amount
    mapping(address => uint256) public stakedAmount;

    // Total amount of staking tokens currently staked
    uint256 public totalStakedAmount;

    // Minimum staking amount
    uint256 public minStakeAmount;

    // Maximum staking amount
    uint256 public maxStakeAmount;

    // Staking fee in basis points (e.g., 100 for 1%)
    uint16 public stakingFeeBasisPoints;

    // Event for successful staking
    event Staked(address indexed user, uint256 amount);

    // Event for successful unstaking
    event Unstaked(address indexed user, uint256 amount);

    // Event for updating staking fee
    event StakingFeeUpdated(uint16 newFee);

    // Event for updating min/max stake amounts
    event StakeLimitsUpdated(uint256 minAmount, uint256 maxAmount);

    constructor(address _stakingTokenAddress, uint256 _minStakeAmount, uint256 _maxStakeAmount, uint16 _stakingFeeBasisPoints) ERC20(NAME, SYMBOL) {
        require(_stakingTokenAddress != address(0), "Staking token cannot be zero address");
        stakingToken = IERC20(_stakingTokenAddress);
        minStakeAmount = _minStakeAmount;
        maxStakeAmount = _maxStakeAmount;
        stakingFeeBasisPoints = _stakingFeeBasisPoints;
    }

    /**
     * @notice Stake the underlying token. Mints stTokens to the user.
     * @param _amount The amount of staking tokens to stake.
     */
    function stake(uint256 _amount) external {
        require(_amount >= minStakeAmount, "Amount below minimum stake");
        require(_amount <= maxStakeAmount, "Amount above maximum stake");

        // Transfer staking tokens from user to this contract
        require(stakingToken.transferFrom(msg.sender, address(this), _amount), "Transfer failed");

        // Mint stTokens to the user
        uint256 stTokensToMint = _calculateStTokensToMint(_amount);
        _mint(msg.sender, stTokensToMint);

        // Update internal tracking
        stakedAmount[msg.sender] = stakedAmount[msg.sender].add(_amount);
        totalStakedAmount = totalStakedAmount.add(_amount);

        emit Staked(msg.sender, _amount);
    }

    /**
     * @notice Unstake the underlying token. Burns stTokens from the user.
     * @param _amount The amount of stTokens to burn.
     */
    function unstake(uint256 _amount) external {
        require(_amount > 0, "Amount must be greater than zero");
        require(balanceOf(msg.sender) >= _amount, "Insufficient stToken balance");

        // Calculate unstake amount, considering potential fee
        uint256 unstakeAmount = _calculateUnstakeAmount(_amount);
        uint256 feeAmount = _amount.sub(unstakeAmount);

        // Burn stTokens from the user
        _burn(msg.sender, _amount);

        // Transfer staking tokens back to the user
        require(stakingToken.transfer(msg.sender, unstakeAmount), "Transfer failed");

        // Update internal tracking
        stakedAmount[msg.sender] = stakedAmount[msg.sender].sub(unstakeAmount);
        totalStakedAmount = totalStakedAmount.sub(unstakeAmount);

        // If there was a fee, send it to the contract owner
        if (feeAmount > 0) {
            // Assuming the fee is taken in staking tokens
            // This logic might need adjustment based on fee collection mechanism
            // For simplicity, we assume the fee is directly deducted from the unstake amount
            // A more sophisticated approach might involve a separate fee pool
            // For now, we'll just log it and assume it's handled by the fee calculation itself.
            // If you want to send the fee to the owner, you'd need to ensure the contract holds enough staking tokens.
            // This current implementation implies the fee is effectively a loss for the staker on unstake.
        }

        emit Unstaked(msg.sender, unstakeAmount);
    }

    /**
     * @notice Calculate the amount of stTokens to mint for a given staking amount.
     * @param _stakingAmount The amount of staking tokens.
     * @return The amount of stTokens to mint.
     */
    function _calculateStTokensToMint(uint256 _stakingAmount) internal view returns (uint256) {
        // In a simple model, 1 stToken represents 1 staking token.
        // More complex models could involve changing exchange rates based on accrued rewards.
        // For this basic version, the exchange rate is 1:1.
        return _stakingAmount;
    }

    /**
     * @notice Calculate the amount of staking tokens to unstake for a given stToken amount.
     * @param _stTokenAmount The amount of stTokens to burn.
     * @return The amount of staking tokens to return to the user.
     */
    function _calculateUnstakeAmount(uint256 _stTokenAmount) internal view returns (uint256) {
        // Calculate the fee to be deducted
        uint256 feeAmountBasisPoints = _stTokenAmount.mul(stakingFeeBasisPoints).div(10000);
        return _stTokenAmount.sub(feeAmountBasisPoints);
    }

    /**
     * @notice Update the minimum staking amount.
     * @param _minAmount The new minimum staking amount.
     */
    function updateMinStakeAmount(uint256 _minAmount) external onlyOwner {
        require(_minAmount > 0, "Minimum stake must be positive");
        minStakeAmount = _minAmount;
        emit StakeLimitsUpdated(minStakeAmount, maxStakeAmount);
    }

    /**
     * @notice Update the maximum staking amount.
     * @param _maxAmount The new maximum staking amount.
     */
    function updateMaxStakeAmount(uint256 _maxAmount) external onlyOwner {
        require(_maxAmount >= minStakeAmount, "Maximum stake must be greater than or equal to minimum stake");
        maxStakeAmount = _maxAmount;
        emit StakeLimitsUpdated(minStakeAmount, maxStakeAmount);
    }

    /**
     * @notice Update the staking fee in basis points.
     * @param _feeBasisPoints The new staking fee in basis points (e.g., 100 for 1%).
     */
    function updateStakingFee(uint16 _feeBasisPoints) external onlyOwner {
        require(_feeBasisPoints <= 10000, "Fee cannot exceed 100%"); // Max 100% fee
        stakingFeeBasisPoints = _feeBasisPoints;
        emit StakingFeeUpdated(_feeBasisPoints);
    }

    /**
     * @notice Allows the owner to withdraw any staking tokens accidentally sent to the contract.
     */
    function withdrawStakingTokens() external onlyOwner {
        uint256 balance = stakingToken.balanceOf(address(this));
        require(balance > 0, "No staking tokens to withdraw");
        stakingToken.transfer(owner(), balance);
    }

    /**
     * @notice Get the user's current staked amount.
     * @param _user The address of the user.
     * @return The staked amount.
     */
    function getUserStakedAmount(address _user) external view returns (uint256) {
        return stakedAmount[_user];
    }

    /**
     * @notice Get the total staked amount in the protocol.
     * @return The total staked amount.
     */
    function getTotalStakedAmount() external view returns (uint256) {
        return totalStakedAmount;
    }
}

