import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/math/SafeMath.sol";

interface IStrategy {
    function deposit(uint256 _amount) external;
    function withdraw(uint256 _amount) external;
    function harvest() external returns (uint256 _earned);
    function withdrawAll() external returns (uint256 _balance);
    function balanceOf() external view returns (uint256);
    function getRewardToken() external view returns (IERC20);
    function getUnderlyingToken() external view returns (IERC20);
}

contract YieldAggregatorVault is Ownable {
    using SafeMath for uint256;

    IERC20 public underlyingToken;
    IStrategy public strategy;

    mapping(address => uint256) public balanceOf;
    uint256 public totalShares;

    uint256 public depositFeeBP; // Basis points for deposit fee (e.g., 100 for 1%)
    uint256 public withdrawalFeeBP; // Basis points for withdrawal fee (e.g., 50 for 0.5%)
    uint256 public managementFeeBP; // Basis points for management fee (e.g., 200 for 2%)

    address public performanceFeeRecipient;

    event Deposit(address indexed user, uint256 amount, uint256 shares);
    event Withdraw(address indexed user, uint256 amount, uint256 shares);
    event StrategyHarvested(uint256 harvestedAmount);
    event FeesCollected(uint256 depositFees, uint256 withdrawalFees, uint256 managementFees);

    constructor(
        address _underlyingToken,
        address _strategy,
        uint256 _depositFeeBP,
        uint256 _withdrawalFeeBP,
        uint256 _managementFeeBP,
        address _performanceFeeRecipient
    ) {
        underlyingToken = IERC20(_underlyingToken);
        strategy = IStrategy(_strategy);
        depositFeeBP = _depositFeeBP;
        withdrawalFeeBP = _withdrawalFeeBP;
        managementFeeBP = _managementFeeBP;
        performanceFeeRecipient = _performanceFeeRecipient;

        require(address(underlyingToken) != address(0), "Vault: Invalid underlying token address");
        require(address(strategy) != address(0), "Vault: Invalid strategy address");
        require(performanceFeeRecipient != address(0), "Vault: Invalid performance fee recipient");
        require(_depositFeeBP <= 10000, "Vault: Deposit fee too high"); // Max 100%
        require(_withdrawalFeeBP <= 10000, "Vault: Withdrawal fee too high"); // Max 100%
        require(_managementFeeBP <= 10000, "Vault: Management fee too high"); // Max 100%
    }

    function deposit(uint256 _amount) external {
        require(_amount > 0, "Vault: Deposit amount must be greater than 0");

        // Calculate deposit fee
        uint256 depositFee = _amount.mul(depositFeeBP).div(10000);
        uint256 amountAfterFee = _amount.sub(depositFee);

        // Transfer underlying tokens to the vault
        require(underlyingToken.transferFrom(msg.sender, address(this), _amount), "Vault: Token transfer failed");

        // Transfer deposit fee to performance fee recipient (or treasury)
        if (depositFee > 0) {
            underlyingToken.transfer(performanceFeeRecipient, depositFee);
            emit FeesCollected(depositFee, 0, 0);
        }

        // Calculate shares based on current vault value
        uint256 shares = 0;
        if (totalShares == 0) {
            shares = amountAfterFee; // First deposit, 1:1 ratio
        } else {
            uint256 vaultValue = getVaultValue();
            shares = amountAfterFee.mul(totalShares).div(vaultValue);
        }

        balanceOf[msg.sender] = balanceOf[msg.sender].add(shares);
        totalShares = totalShares.add(shares);

        // Deposit to strategy
        strategy.deposit(amountAfterFee);

        emit Deposit(msg.sender, _amount, shares);
    }

    function withdraw(uint256 _shares) external {
        require(_shares > 0, "Vault: Withdraw shares must be greater than 0");
        require(balanceOf[msg.sender] >= _shares, "Vault: Insufficient shares");

        // Calculate amount to withdraw from strategy
        uint256 vaultValue = getVaultValue();
        uint256 amountToWithdraw = _shares.mul(vaultValue).div(totalShares);

        // Update user's shares and total shares
        balanceOf[msg.sender] = balanceOf[msg.sender].sub(_shares);
        totalShares = totalShares.sub(_shares);

        // Withdraw from strategy
        strategy.withdraw(amountToWithdraw);
        uint256 withdrawnAmount = underlyingToken.balanceOf(address(this)); // Amount received from strategy

        // Calculate withdrawal fee
        uint256 withdrawalFee = withdrawnAmount.mul(withdrawalFeeBP).div(10000);
        uint256 amountAfterFee = withdrawnAmount.sub(withdrawalFee);

        // Transfer withdrawal fee to performance fee recipient (or treasury)
        if (withdrawalFee > 0) {
            underlyingToken.transfer(performanceFeeRecipient, withdrawalFee);
            emit FeesCollected(0, withdrawalFee, 0);
        }

        // Transfer remaining amount to user
        require(underlyingToken.transfer(msg.sender, amountAfterFee), "Vault: Token transfer failed");

        emit Withdraw(msg.sender, amountAfterFee, _shares);
    }

    function harvest() external onlyOwner {
        // Harvest rewards from the strategy
        uint256 harvestedAmount = strategy.harvest();
        emit StrategyHarvested(harvestedAmount);

        // Calculate management fee
        uint256 managementFee = harvestedAmount.mul(managementFeeBP).div(10000);
        uint256 amountAfterManagementFee = harvestedAmount.sub(managementFee);

        // Transfer management fee to performance fee recipient (or treasury)
        if (managementFee > 0) {
            underlyingToken.transfer(performanceFeeRecipient, managementFee);
            emit FeesCollected(0, 0, managementFee);
        }

        // Deposit remaining harvested amount back into the strategy for auto-compounding
        if (amountAfterManagementFee > 0) {
            strategy.deposit(amountAfterManagementFee);
        }
    }

    function getVaultValue() public view returns (uint256) {
        // The vault value is the amount of underlying tokens currently held by the strategy + vault itself
        // For simplicity, we assume the strategy holds all deposited assets and returns its balance.
        // In a more complex scenario, you might need to track vault's own balance too.
        return underlyingToken.balanceOf(address(strategy)).add(underlyingToken.balanceOf(address(this)));
    }

    function getUserShares(address _user) external view returns (uint256) {
        return balanceOf[_user];
    }

    function getUserAmount(address _user) external view returns (uint256) {
        uint256 userShares = balanceOf[_user];
        if (userShares == 0) return 0;
        uint256 vaultValue = getVaultValue();
        return userShares.mul(vaultValue).div(totalShares);
    }

    function setDepositFee(uint256 _depositFeeBP) external onlyOwner {
        require(_depositFeeBP <= 10000, "Vault: Deposit fee too high");
        depositFeeBP = _depositFeeBP;
    }

    function setWithdrawalFee(uint256 _withdrawalFeeBP) external onlyOwner {
        require(_withdrawalFeeBP <= 10000, "Vault: Withdrawal fee too high");
        withdrawalFeeBP = _withdrawalFeeBP;
    }

    function setManagementFee(uint256 _managementFeeBP) external onlyOwner {
        require(_managementFeeBP <= 10000, "Vault: Management fee too high");
        managementFeeBP = _managementFeeBP;
    }

    function setPerformanceFeeRecipient(address _performanceFeeRecipient) external onlyOwner {
        require(_performanceFeeRecipient != address(0), "Vault: Invalid performance fee recipient");
        performanceFeeRecipient = _performanceFeeRecipient;
    }

    function setStrategy(address _newStrategy) external onlyOwner {
        require(_newStrategy != address(0), "Vault: Invalid strategy address");
        // Optionally, you might want to withdraw all assets from the old strategy before setting a new one.
        strategy = IStrategy(_newStrategy);
    }

    function withdrawAllFromStrategy() external onlyOwner {
        // This is a safety function to withdraw all assets from the strategy if needed.
        // It should be used with caution.
        strategy.withdrawAll();
    }

    function emergencyWithdraw(address _token, address _to) external onlyOwner {
        // Emergency withdrawal function for the vault's own balance of a specific token.
        // This bypasses the strategy and fees. Use with extreme caution.
        uint256 balance = IERC20(_token).balanceOf(address(this));
        require(balance > 0, "Vault: No balance to withdraw");
        require(IERC20(_token).transfer(_to, balance), "Vault: Emergency transfer failed");
    }
}

