contract QuadraticVotingDAO is Ownable {
    using SafeMath for uint256;

    IERC20 public immutable votingToken;
    uint256 public proposalThreshold; // Minimum tokens required to create a proposal
    uint256 public votingDelay; // Blocks to wait before voting starts
    uint256 public votingPeriod; // Blocks a proposal is active for voting

    struct Proposal {
        uint256 id;
        address proposer;
        string description;
        uint256 creationBlock;
        uint256 startBlock;
        uint256 endBlock;
        uint256 forVotes;
        uint256 againstVotes;
        mapping(address => bool) hasVoted;
        bool executed;
    }

    Proposal[] public proposals;
    uint256 public nextProposalId;

    event ProposalCreated(
        uint256 id,
        address proposer,
        string description,
        uint256 creationBlock,
        uint256 startBlock,
        uint256 endBlock
    );
    event Voted(uint256 proposalId, address voter, bool support, uint256 votingPower);
    event ProposalExecuted(uint256 proposalId);

    constructor(
        address _votingTokenAddress,
        uint256 _proposalThreshold,
        uint256 _votingDelay,
        uint256 _votingPeriod
    ) {
        votingToken = IERC20(_votingTokenAddress);
        proposalThreshold = _proposalThreshold;
        votingDelay = _votingDelay;
        votingPeriod = _votingPeriod;
        nextProposalId = 0;
    }

    function getVotingPower(address _voter) public view returns (uint256) {
        uint256 balance = votingToken.balanceOf(_voter);
        // Quadratic voting: voting power is sqrt(balance)
        // We can approximate sqrt by iterating or using a more complex algorithm if high precision is needed.
        // For simplicity, a basic integer square root is used here.
        // Note: This is a simplified integer square root, consider a more robust implementation for production.
        uint256 power = 0;
        uint256 guess = balance / 2;
        if (guess == 0) guess = 1;
        uint256 guessSquared = guess.mul(guess);

        while (guessSquared > balance) {
            guess = guess / 2;
            guessSquared = guess.mul(guess);
        }
        while (guessSquared < balance) {
            guess = guess.add(1);
            guessSquared = guess.mul(guess);
        }
        power = guess.sub(1); // Adjust if guessSquared is exactly balance or slightly over

        if (power.mul(power) > balance) {
            power = power.sub(1);
        }

        return power;
    }


    function createProposal(string memory _description) public {
        require(votingToken.balanceOf(msg.sender) >= proposalThreshold, "Not enough tokens to create proposal");

        uint256 currentBlock = block.number;
        uint256 proposalId = nextProposalId++;

        proposals.push(Proposal({
            id: proposalId,
            proposer: msg.sender,
            description: _description,
            creationBlock: currentBlock,
            startBlock: currentBlock.add(votingDelay),
            endBlock: currentBlock.add(votingDelay).add(votingPeriod),
            forVotes: 0,
            againstVotes: 0,
            executed: false
        }));

        emit ProposalCreated(proposalId, msg.sender, _description, currentBlock, currentBlock.add(votingDelay), currentBlock.add(votingDelay).add(votingPeriod));
    }

    function vote(uint256 _proposalId, bool _support) public {
        require(_proposalId < nextProposalId, "Proposal does not exist");
        Proposal storage proposal = proposals[_proposalId];

        require(block.number >= proposal.startBlock, "Voting has not started yet");
        require(block.number <= proposal.endBlock, "Voting period has ended");
        require(!proposal.hasVoted[msg.sender], "Already voted");

        uint256 votingPower = getVotingPower(msg.sender);
        require(votingPower > 0, "No voting power");

        proposal.hasVoted[msg.sender] = true;

        if (_support) {
            proposal.forVotes = proposal.forVotes.add(votingPower);
        } else {
            proposal.againstVotes = proposal.againstVotes.add(votingPower);
        }

        emit Voted(_proposalId, msg.sender, _support, votingPower);
    }

    function executeProposal(uint256 _proposalId) public onlyOwner {
        require(_proposalId < nextProposalId, "Proposal does not exist");
        Proposal storage proposal = proposals[_proposalId];

        require(block.number > proposal.endBlock, "Voting period has not ended yet");
        require(!proposal.executed, "Proposal already executed");

        // Simple majority check (can be customized, e.g., quorum)
        if (proposal.forVotes > proposal.againstVotes) {
            proposal.executed = true;
            // In a real DAO, you would implement the actual logic here based on the proposal description.
            // For example, calling a function on another contract, transferring funds, etc.
            // This is a placeholder.
            emit ProposalExecuted(_proposalId);
        } else {
            // Optionally, you could have a way to cancel or mark as failed
            // For now, just don't mark as executed if it doesn't pass.
        }
    }

    function getProposal(uint256 _proposalId) public view returns (
        uint256 id,
        address proposer,
        string memory description,
        uint256 creationBlock,
        uint256 startBlock,
        uint256 endBlock,
        uint256 forVotes,
        uint256 againstVotes,
        bool executed
    ) {
        require(_proposalId < nextProposalId, "Proposal does not exist");
        Proposal storage p = proposals[_proposalId];
        return (
            p.id,
            p.proposer,
            p.description,
            p.creationBlock,
            p.startBlock,
            p.endBlock,
            p.forVotes,
            p.againstVotes,
            p.executed
        );
    }

    // Helper to get the number of proposals
    function getNumberOfProposals() public view returns (uint256) {
        return nextProposalId;
    }
}

