import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Address.sol";

contract SocialRecoveryWallet is Ownable {
    using Address for address;

    struct RecoveryRequest {
        address proposedOwner;
        uint256 creationTime;
        uint256 confirmationCount;
        mapping(address => bool) confirmers;
    }

    address[] public guardians;
    uint256 public constant CONFIRMATION_THRESHOLD = 2; // Minimum number of guardians to confirm a recovery
    uint256 public constant RECOVERY_TIMEOUT = 7 days; // Time limit for a recovery request to be confirmed

    mapping(address => bool) public isGuardian;
    mapping(address => RecoveryRequest) public recoveryRequests;

    event GuardianAdded(address indexed guardian);
    event GuardianRemoved(address indexed guardian);
    event RecoveryInitiated(address indexed proposedOwner, address indexed initiator);
    event RecoveryConfirmed(address indexed proposedOwner, address indexed confirmer);
    event RecoveryExecuted(address indexed newOwner);
    event OwnerUpdated(address indexed newOwner);

    modifier onlyGuardian() {
        require(isGuardian[msg.sender], "Not a guardian");
        _;
    }

    constructor(address[] memory _guardians) Ownable(msg.sender) {
        for (uint256 i = 0; i < _guardians.length; i++) {
            address guardian = _guardians[i];
            require(guardian != address(0), "Invalid guardian address");
            require(!isGuardian[guardian], "Guardian already added");
            guardians.push(guardian);
            isGuardian[guardian] = true;
            emit GuardianAdded(guardian);
        }
    }

    function addGuardian(address _guardian) public onlyOwner {
        require(_guardian != address(0), "Invalid guardian address");
        require(!isGuardian[_guardian], "Guardian already exists");
        guardians.push(_guardian);
        isGuardian[_guardian] = true;
        emit GuardianAdded(_guardian);
    }

    function removeGuardian(address _guardian) public onlyOwner {
        require(isGuardian[_guardian], "Guardian not found");

        // Remove from guardians array
        for (uint256 i = 0; i < guardians.length; i++) {
            if (guardians[i] == _guardian) {
                guardians[i] = guardians[guardians.length - 1];
                guardians.pop();
                break;
            }
        }
        isGuardian[_guardian] = false;
        emit GuardianRemoved(_guardian);
    }

    function initiateRecovery(address _proposedOwner) public onlyGuardian {
        require(_proposedOwner != address(0), "Invalid proposed owner address");
        require(_proposedOwner != owner(), "Proposed owner is already the owner");
        require(recoveryRequests[_proposedOwner].creationTime == 0, "Recovery already in progress for this address");

        RecoveryRequest storage request = recoveryRequests[_proposedOwner];
        request.proposedOwner = _proposedOwner;
        request.creationTime = block.timestamp;
        request.confirmationCount = 0;
        // Clear previous confirmers if any
        for (uint256 i = 0; i < guardians.length; i++) {
            delete request.confirmers[guardians[i]];
        }

        emit RecoveryInitiated(_proposedOwner, msg.sender);
    }

    function confirmRecovery(address _proposedOwner) public onlyGuardian {
        require(_proposedOwner != address(0), "Invalid proposed owner address");
        require(_proposedOwner != owner(), "Proposed owner is already the owner");

        RecoveryRequest storage request = recoveryRequests[_proposedOwner];
        require(request.creationTime != 0, "No recovery request in progress for this address");
        require(block.timestamp < request.creationTime + RECOVERY_TIMEOUT, "Recovery request has expired");
        require(!request.confirmers[msg.sender], "Guardian has already confirmed");

        request.confirmers[msg.sender] = true;
        request.confirmationCount++;

        emit RecoveryConfirmed(_proposedOwner, msg.sender);

        if (request.confirmationCount >= CONFIRMATION_THRESHOLD) {
            executeRecovery(_proposedOwner);
        }
    }

    function executeRecovery(address _newOwner) private {
        require(recoveryRequests[_newOwner].creationTime != 0, "No recovery request in progress");
        require(recoveryRequests[_newOwner].confirmationCount >= CONFIRMATION_THRESHOLD, "Not enough confirmations");
        require(block.timestamp < recoveryRequests[_newOwner].creationTime + RECOVERY_TIMEOUT, "Recovery request has expired");

        address oldOwner = owner();
        _transferOwnership(_newOwner); // Use OpenZeppelin's _transferOwnership

        // Clear the recovery request
        delete recoveryRequests[_newOwner];

        emit RecoveryExecuted(_newOwner);
        emit OwnerUpdated(_newOwner);
    }

    function cancelRecovery(address _proposedOwner) public onlyGuardian {
        require(recoveryRequests[_proposedOwner].creationTime != 0, "No recovery request in progress for this address");
        require(msg.sender == owner() || msg.sender == recoveryRequests[_proposedOwner].proposedOwner, "Only owner or proposed owner can cancel"); // Allow owner or the proposed owner to cancel

        // Clear the recovery request
        delete recoveryRequests[_proposedOwner];
        emit RecoveryInitiated(_proposedOwner, address(0)); // Indicate cancellation with zero initiator
    }

    function getGuardians() public view returns (address[] memory) {
        return guardians;
    }

    function isGuardianAddress(address _addr) public view returns (bool) {
        return isGuardian[_addr];
    }

    function getRecoveryRequest(address _proposedOwner) public view returns (address proposedOwner, uint256 creationTime, uint256 confirmationCount) {
        RecoveryRequest storage request = recoveryRequests[_proposedOwner];
        return (request.proposedOwner, request.creationTime, request.confirmationCount);
    }

    // Fallback and receive functions to allow the wallet to hold ETH
    receive() external payable {}
    fallback() external payable {}
}
